import { createRequire } from 'node:module';
import { mkdir } from 'node:fs/promises';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const failures = [];
const out = '/tmp/opencode';
await mkdir(out, { recursive: true });
try {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const page = await context.newPage();
  page.on('pageerror', e => failures.push(e.message));
  page.on('console', m => { if (m.type() === 'error') failures.push(m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(1500);
  console.log('canvas', await page.locator('#world').evaluate(c => `${c.width}x${c.height}`));
  console.log('start visible', await page.locator('#begin-btn').isVisible());
  console.log('guide mobile text', await page.locator('.guide-grid').innerText());
  await page.locator('#begin-btn').click();
  await page.waitForTimeout(1100);
  console.log('mobile controls visible', await page.locator('.mobile-controls').isVisible());
  await page.screenshot({ path: `${out}/frontier-mobile.jpg`, type: 'jpeg', quality: 88 });
  await page.locator('#touch-build').click();
  console.log('build menu open', await page.locator('#build-dock').evaluate(e => e.classList.contains('open')));
  await page.locator('[data-build="miner"]').click();
  console.log('save after deploy', await page.evaluate(() => localStorage.getItem('frontier-save')));
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${out}/frontier-build.jpg`, type: 'jpeg', quality: 88 });
  const joy = await page.locator('#joystick').boundingBox();
  await page.mouse.move(joy.x + joy.width / 2, joy.y + joy.height / 2);
  await page.mouse.down();
  await page.mouse.move(joy.x + joy.width / 2 + 28, joy.y + joy.height / 2, { steps: 4 });
  await page.waitForTimeout(350);
  console.log('joystick responds', await page.locator('#joy-knob').evaluate(e => e.style.transform));
  await page.mouse.up();
  await page.locator('#touch-mine').click();
  console.log('harvest button responds', await page.locator('#notification').innerText());
  await context.close();
  const reloadContext = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const reload = await reloadContext.newPage();
  await reload.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 45000 });
  console.log('restored objective', await reload.locator('#objective-text').innerText());
  console.log('overflow', await reload.evaluate(() => ({ x: document.documentElement.scrollWidth, width: innerWidth, y: document.documentElement.scrollHeight, height: innerHeight })));
  await reload.locator('#begin-btn').click();
  await reload.waitForTimeout(1000);
  await reload.screenshot({ path: `${out}/frontier-restored.jpg`, type: 'jpeg', quality: 88 });
  await reloadContext.close();
  const desk = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await desk.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 45000 });
  await desk.locator('#begin-btn').click();
  await desk.waitForTimeout(1000);
  await desk.screenshot({ path: `${out}/frontier-desktop.jpg`, type: 'jpeg', quality: 88 });
  console.log('desktop overflow', await desk.evaluate(() => ({ x: document.documentElement.scrollWidth, width: innerWidth, y: document.documentElement.scrollHeight, height: innerHeight })));
  await desk.close();
} finally { await browser.close(); }
console.log('failures', failures);
if (failures.length) process.exitCode = 1;

